import{_ as a}from"./chunks/library-overview.Bu864uIA.js";import{_ as t,o,c as n,a2 as r}from"./chunks/framework.Dx-TCpNt.js";const u=JSON.parse('{"title":"Preparing & Renaming Images","description":"KomaYomi reads image folders in place. It never copies or converts your files, and it only renames or splits them when you explicitly ask for it in the…","frontmatter":{"description":"KomaYomi reads image folders in place. It never copies or converts your files, and it only renames or splits them when you explicitly ask for it in the…"},"headers":[],"relativePath":"guide/preprocess.md","filePath":"guide/preprocess.md","lastUpdated":1794814645000}'),i={name:"guide/preprocess.md"};function s(l,e,d,p,h,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="preparing-renaming-images" tabindex="-1">Preparing &amp; Renaming Images <a class="header-anchor" href="#preparing-renaming-images" aria-label="Permalink to &quot;Preparing &amp; Renaming Images&quot;">​</a></h1><p>KomaYomi reads image folders in place. It never copies or converts your files, and it only renames or splits them when you explicitly ask for it in the preprocessing wizard. That means the minutes you spend tidying a volume before adding it decide how well detection, page pairing and compare reading go. Slightly annoying, much cheaper than fixing the same page three times.</p><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Panel detection is happiest with clean page scans. A volume with rotated pages, scanner borders, a pile of AVIF/HEIC files or one edition missing a page will still open, but every later step — pairing, alignment, notes, export — inherits the mess. Fix it once, at the source.</p><h2 id="what-komayomi-does-with-your-files" tabindex="-1">What KomaYomi does with your files <a class="header-anchor" href="#what-komayomi-does-with-your-files" aria-label="Permalink to &quot;What KomaYomi does with your files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Behaviour</th><th>Consequence</th></tr></thead><tbody><tr><td>Images are read from the folder you point at.</td><td>Nothing is imported or duplicated; edits stay in <code>data/</code>. Renaming and splitting happen only when you use the wizard.</td></tr><tr><td>Pages are paired by <strong>sorted position</strong>, not by filename.</td><td>Renaming changes the order. Insert one page and every later page shifts.</td></tr><tr><td>Sorting is natural: digit runs compare as numbers.</td><td><code>2.jpg</code> comes before <code>10.jpg</code> even without zero padding.</td></tr><tr><td>WebP is decoded for detection and splitting; AVIF, HEIC, GIF and BMP are not.</td><td>Convert AVIF/HEIC/GIF/BMP to JPEG or PNG if you rely on <strong>Auto split</strong>. Splitting a WebP page works and writes PNG halves.</td></tr><tr><td>One image is one page.</td><td>A scanned spread must be split in every language, either in the wizard or before importing.</td></tr></tbody></table><figure class="shot"><img src="'+a+'" alt="Library sidebar with volumes, chapters and language badges after a clean import"><figcaption>A prepared volume: one folder per language, one folder per chapter, and matching page counts so the language badges line up.</figcaption></figure><h2 id="a-preparation-checklist" tabindex="-1">A preparation checklist <a class="header-anchor" href="#a-preparation-checklist" aria-label="Permalink to &quot;A preparation checklist&quot;">​</a></h2><p>Work on a copy if the originals matter. The order below matters more than the tools you use.</p><ol><li><strong>Rotate and deskew.</strong> Reading direction is stored per page; a sideways scan cannot be fixed by the compare reader.</li><li><strong>Crop scanner borders and facing-page shadows.</strong> Panels that touch the edge are detected more reliably when the page edge is square.</li><li><strong>Convert AVIF, HEIC, GIF or BMP to JPEG or PNG</strong> if you want automatic splitting; WebP pages can stay as they are. Keep the quality high enough that the lettering stays legible.</li><li><strong>One chapter per folder.</strong> Do not mix two chapters in one directory; the chapter becomes the unit for templates, alignment presets and export.</li><li><strong>Remove non-page images</strong> such as covers, credits, colour inserts or bonus art that does not exist in the other editions. One extra page shifts every page after it.</li><li><strong>Keep spreads unsplit, or split every edition at the same place.</strong> A spread counts as one page. If you split the Japanese raw but not the Chinese scanlation, page 12 in one language becomes pages 12–13 in the other and pairing breaks. Use <strong>Split…</strong> in the wizard so every language is cut at once.</li><li><strong>Normalise filenames only if it helps you.</strong> Zero-padded numbers (<code>001.jpg</code>) make diffs and manual checks easier, but the scanner uses sorted position and natural order, so <code>1.jpg</code> and <code>001.jpg</code> both work. <strong>Rename files</strong> in the wizard renumbers a whole chapter and moves the saved page data with it.</li></ol><h2 id="renaming-and-splitting-inside-komayomi" tabindex="-1">Renaming and splitting inside KomaYomi <a class="header-anchor" href="#renaming-and-splitting-inside-komayomi" aria-label="Permalink to &quot;Renaming and splitting inside KomaYomi&quot;">​</a></h2><p>Open <strong>Preprocess…</strong> and pick the volume. Besides titles, page order, exclusions and page roles, each chapter section has a <strong>Files on disk</strong> area with two real file operations. Image format conversion is still not part of the app.</p><p><strong>Batch rename.</strong> Choose a prefix, a start number and the number of digits, then press <strong>Rename files</strong>. The images are renumbered in the page order shown above the button — the order you arranged with the arrow buttons — and the files on disk are genuinely renamed (<code>001.jpg</code>, <code>002.jpg</code>, … keeping each file&#39;s extension). Every language in the chapter that contains all pages is renamed in the same pass, so page <em>n</em> stays the same artwork in every language. Languages with a missing page are left untouched and listed in the result message.</p><p>Page data, history, exclusions, page roles and the saved order are keyed by page index, so they are moved and re-pointed in the same transaction. An in-app rename therefore does not orphan annotations, notes or panel edits. Renaming reloads the volume, so apply other wizard changes first; unsaved drafts are discarded.</p><p>Before anything moves, a manifest is written to <code>data/file-ops/</code>. It lists every old and new name. If a rename fails midway, the whole batch is rolled back, the manifest is marked <code>rolled-back</code>, and the folder is left exactly as it was. A target name that already belongs to another file is refused with an error instead of being overwritten.</p><p><strong>Split a page.</strong> Press <strong>Split…</strong> under a page, choose <strong>Left / right</strong> for a spread or <strong>Top / bottom</strong>, set the cut position as a percentage and confirm. The image is cut into <code>&lt;name&gt;-a</code> and <code>&lt;name&gt;-b</code>; the second half becomes the next page and every later page shifts down. Every language that contains this page is cut at the same position, so pairing stays intact. Splitting accepts PNG, JPEG and WebP; WebP halves are written as PNG. GIF and BMP are refused. The original image is copied to <code>data/file-ops/</code> before it is removed.</p><p>The page document is clipped into both halves: panels and annotations on a half are kept there with rescaled coordinates, panel notes follow their panel, and page-level notes stay on the first half. Both halves keep the page&#39;s reading direction. Check both pages afterwards, especially when the cut crossed a panel.</p><div class="warning custom-block"><p class="custom-block-title">Renaming and splitting cannot be undone from the wizard</p><p>The <strong>Restore previous</strong> banner only rolls back <code>library.json</code>. File renames and splits are one-way in the UI; use the manifest and backup folder under <code>data/file-ops/</code> if you need the previous names or images. Renaming outside the app is still unsafe: page data is keyed by page index, so Explorer/shell renames do not move annotations.</p></div><h2 id="verify-before-you-annotate" tabindex="-1">Verify before you annotate <a class="header-anchor" href="#verify-before-you-annotate" aria-label="Permalink to &quot;Verify before you annotate&quot;">​</a></h2><ol><li>Add the volume and open it in the sidebar.</li><li>Read the warnings on the volume and chapter rows. <em>Page counts differ across languages</em> and <em>Filename does not match page number</em> usually mean a preparation mistake.</li><li>If the folder shape is unusual, open <strong>Folder rules…</strong> and use its preview before saving; see <a href="/KomaYomi-docs/guide/folder-rules">Folder Detection Rules</a>.</li><li>Open the first, middle and last page. Confirm that the same panel really contains the same artwork in every language; if not, the page counts or the spread handling are wrong.</li><li>Only then run <strong>Auto split</strong> and start writing notes.</li></ol><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>One language is one page longer.</strong> Usually an extra cover or credits page. Remove it or add the equivalent page to the other languages.</li><li><strong>A spread is split in only one edition.</strong> Keep spreads whole, or split every edition at the same place.</li><li><strong>Auto split produces nonsense on an AVIF or HEIC page.</strong> Convert the file; detection does not decode AVIF, HEIC, GIF or BMP.</li><li><strong>Renaming shifted a note to the next page.</strong> Page data is keyed by index, so renames done in Explorer or a shell do not move it. Use <strong>Rename files</strong> in the wizard, or rename before annotating.</li><li><strong>The split cut through a panel.</strong> Pick a cut position between panels, or correct the panels on both halves afterwards. Page-level notes stay on the first half by design.</li><li><strong>Pages look fine but thumbnails are mixed.</strong> Thumbnails follow the file content, not the extension; a <code>.png</code> that is really a JPEG still renders. This is cosmetic.</li><li><strong>Folders were reorganised after annotating.</strong> Detection ids changed, so old page data is not found. Apply folder rules before annotating, not after.</li></ul><h2 id="missing-screenshots" tabindex="-1">Missing screenshots <a class="header-anchor" href="#missing-screenshots" aria-label="Permalink to &quot;Missing screenshots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>Needed for</th></tr></thead><tbody><tr><td>before/after page naming</td><td>The zero-padding, natural-sort and <strong>Files on disk</strong> panel</td></tr><tr><td>split form</td><td>Direction and cut position for a scanned spread</td></tr><tr><td>spread handling</td><td>One spread kept as a single page versus split pages</td></tr><tr><td>library warnings strip</td><td>The three warnings used for verification</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/gallery">Library &amp; Import</a> — folder shape, language aliases and volume settings.</li><li><a href="/KomaYomi-docs/guide/folder-rules">Folder Detection Rules</a> — supporting unusual directory layouts.</li><li><a href="/KomaYomi-docs/guide/panels">Panel Workbench</a> — what happens after the first page opens.</li><li><a href="/KomaYomi-docs/guide/project-files">Project Files &amp; Formats</a> — how page data is keyed and versioned.</li><li><a href="/KomaYomi-docs/terminology">Terminology</a> — the shared vocabulary for panels, pages and annotations.</li></ul>',26)])])}const f=t(i,[["render",s]]);export{u as __pageData,f as default};
